import { METRIC_DEFINITIONS } from '../../src/infra/metrics/metric-definitions.js'

// The series as infra/metrics defines them, so that the reference cannot drift from the registry
export function renderMetrics(): string {
  const rows = Object.values<(typeof METRIC_DEFINITIONS)[keyof typeof METRIC_DEFINITIONS]>(
    METRIC_DEFINITIONS
  ).map(({ name, type, labels, help }) => {
    const labelCell = labels.length === 0 ? '-' : labels.map(label => `\`${label}\``).join(', ')
    return `| \`${name}\` | ${type} | ${labelCell} | ${help} |`
  })
  return [
    '<!-- GENERATED by `pnpm docs:gen` from src/infra/metrics/metric-definitions.ts. Do not edit by hand. -->',
    '',
    '# Metrics',
    '',
    '`GET /metrics` answers in the Prometheus text format and requires `Authorization: Bearer <METRICS_TOKEN>`;',
    'when `METRICS_TOKEN` is unset the endpoint is closed.',
    '',
    '| Series | Type | Labels | Meaning |',
    '| --- | --- | --- | --- |',
    ...rows,
    '',
    'Histograms also expose the `_bucket`, `_sum` and `_count` series Prometheus derives from them.',
    'Node.js and process metrics (`process_*`, `nodejs_*`) are exposed as well.',
    ''
  ].join('\n')
}
